/* Shared, proportional time coordinates; regional histories retain their own labels. */
const WORLD_RANGES=[[-3000,2026,1000,['历史全景','Historical panorama']],[0,1500,250,['公元1—1500','1–1500 CE']],[1400,2026,100,['1400年至今','1400–present']]];
const WORLD_ITEMS=[
['eu-antiquity','europe',-800,500,0,'period',['古代','Antiquity'],['希腊城邦与罗马世界，多个政治中心先后并存。','Greek cities and the Roman world, with multiple political centres.'],'greece'],
['eu-medieval','europe',500,1500,0,'period',['中世纪','Middle Ages'],['欧洲常用的宽泛分期，内部包含不同王国、教会和城市的发展；边界为约数。','A broad European convention encompassing kingdoms, churches and cities; boundaries are approximate.'],'medieval'],
['eu-early','europe',1500,1800,0,'period',['近代早期','Early modern'],['宗教改革、王朝竞争、海上扩张与启蒙等过程相互重叠。','Reformation, dynastic rivalry, overseas expansion and Enlightenment overlapped.'],'dynasties'],
['eu-modern','europe',1800,2026,0,'period',['近现代','Modern & contemporary'],['工业化、民族国家、世界大战与战后合作构成不同但相连的历史线索。','Industrialisation, nation states, world wars and postwar cooperation form distinct connected histories.'],'industry'],
['eu-crown','europe',800,800,1,'event',['查理曼加冕','Charlemagne crowned'],['800年：加冕连接王权与教会，也重新提出西欧的帝国理想。','800: coronation connected kingship with the Church and renewed imperial ambitions in western Europe.'],'carolingian'],
['eu-reform','europe',1517,1517,2,'event',['宗教改革节点','Reformation milestone'],['1517年是欧洲宗教改革的重要节点，后续争论与冲突持续跨越多个地区。','1517 marks a major milestone in the European Reformation, followed by prolonged debate and conflict.'],'reformation'],
['af-old','africa',-2700,-2200,0,'period',['埃及 · 古王国','Egypt · Old Kingdom'],['约前2700—前2200年：孟菲斯与金字塔墓地体现王权、仪式和国家组织。','c. 2700–2200 BCE: Memphis and pyramid cemeteries reveal kingship, ritual and state organisation.'],'af-nile'],
['af-new','africa',-1550,-1070,0,'period',['埃及 · 新王国','Egypt · New Kingdom'],['约前1550—前1070年：底比斯神庙、王陵与阿布辛拜勒是相关的观察入口。','c. 1550–1070 BCE: Theban temples, royal tombs and Abu Simbel provide related entry points.'],'af-nile'],
['af-kush','africa',-900,350,1,'period',['尼罗河南部 · 库施','Southern Nile · Kush'],['此处选取纳帕塔与麦罗埃文化的约前900—公元350年，强调南部尼罗河的政治中心。','This view selects the Napatan and Meroitic span, c. 900 BCE–350 CE, highlighting southern Nile political centres.'],'af-kush'],
['af-kairouan','africa',670,670,0,'event',['凯鲁万建城','Kairouan founded'],['670年：北非伊斯兰城市史的一个入口，宗教中心地位后来持续超越政治首都功能。','670: an entry into North African Islamic urban history; religious importance later outlasted capital status.'],'af-islamic'],
['af-zimbabwe','africa',1100,1450,1,'period',['非洲南部 · 大津巴布韦','Southern Africa · Great Zimbabwe'],['约1100—1450年：石筑城市、王室空间与贸易呈现南部非洲的社会组织。','c. 1100–1450: stone-built urban and royal spaces and trade reveal southern African social organisation.'],'af-southern'],
['af-askia','africa',1495,1495,2,'event',['加奥 · 阿斯基亚陵','Gao · Tomb of Askia'],['1495年：陵墓与宗教建筑群体现桑海帝国的王权、信仰和跨撒哈拉贸易财富。','1495: the complex expresses Songhai authority, faith and trans-Saharan trading wealth.'],'af-sahara'],
['af-kongo','africa',1300,1900,3,'period',['中非 · 刚果王国都城','Central Africa · Kongo capital'],['姆班扎刚果在14—19世纪的王国历史中，体现本土制度与基督教传入后的变化；图中边界采用整世纪约数。','Mbanza Kongo illuminates indigenous institutions and changes following Christianity in the kingdom’s 14th–19th-century history; bounds are rounded.'],'af-kingdoms'],
['af-asmara','africa',1893,1941,0,'period',['阿斯马拉 · 殖民城市规划','Asmara · Colonial planning'],['1893—1941年的规划与建设将现代主义建筑和殖民城市中的空间分配联系起来。','Planning and construction in 1893–1941 connect modernist architecture with colonial allocation of urban space.'],'af-modern'],
['af-prison','africa',1960,2000,1,'period',['南非 · 政治监禁','South Africa · Political imprisonment'],['以约1960—2000年为观察窗口，罗本岛政治监禁是理解种族隔离与抵抗的入口；并非全非洲同时期历史的概括。','Using c. 1960–2000 as a viewing window, political imprisonment on Robben Island is an entry into apartheid and resistance, not a summary of the whole continent.'],'af-freedom']
];
let worldRangeIndex=1,worldItemId='eu-medieval';
function renderParallelWorld(){
 const [start,end,step]=WORLD_RANGES[worldRangeIndex],span=end-start;
 const pos=v=>(v-start)/span*100;
 const year=v=>v===0?L('公元1','1 CE'):v<0?L('前'+(-v),(-v)+' BCE'):String(v);
 const visible=WORLD_ITEMS.filter(x=>x[3]>=start&&x[2]<=end);
 if(!visible.some(x=>x[0]===worldItemId))worldItemId=visible[0]?.[0];
 const ticks=[];for(let v=Math.ceil(start/step)*step;v<=end;v+=step)ticks.push(v);
 const continents=[['africa','非洲','Africa'],['antarctica','南极洲','Antarctica'],['asia','亚洲','Asia'],['europe','欧洲','Europe'],['north','北美洲','North America'],['oceania','大洋洲','Oceania'],['southamerica','南美洲','South America']];
 if(ticks[ticks.length-1]!==end){if(end-ticks[ticks.length-1]<step*.4)ticks.pop();ticks.push(end);}
 const item=WORLD_ITEMS.find(x=>x[0]===worldItemId);
 return `<div class="world-windows" aria-label="${L('选择时间范围','Choose a time range')}">${WORLD_RANGES.map((r,i)=>`<button data-world-range="${i}" aria-pressed="${i===worldRangeIndex}">${L(...r[3])}</button>`).join('')}</div><p class="parallel-key">${L('横条：历史时期或过程　圆点与日期：历史事件。各行共用年代比例；区域分期不代表全洲。按住时间轴任意位置左右拖动，或使用触控板横向滚动。','Bars: periods or processes. Dots with dates: events. All rows share a time scale; regional periods do not represent an entire continent. Drag anywhere on the timeline or scroll horizontally with a trackpad.')}</p><div class="parallel-scroll" tabindex="0" role="region" aria-label="${L('各大洲平行时间轴','Parallel continental timelines')}"><div class="parallel-chart"><div class="parallel-row parallel-axis"><div class="parallel-label">${L('年代','Year')}</div><div class="parallel-track">${ticks.map(v=>`<span class="parallel-tick" style="left:${pos(v)}%">${year(v)}</span>`).join('')}</div></div>${continents.map(([id,zh,en])=>{const ready=id==='europe'||id==='africa';return `<section class="parallel-row ${ready?'':'unfilled'}"><div class="parallel-label"><h2>${L(zh,en)}</h2>${ready?`<span class="row-type period-type">${L('时期 / 过程','Periods')}</span><span class="row-type event-type">${L('事件','Events')}</span>`:''}</div><div class="parallel-track" style="height:${ready?460:48}px">${ticks.map(v=>`<i class="parallel-gridline" style="left:${pos(v)}%"></i>`).join('')}${ready?'<div class="parallel-layer-divider"></div>':''}${ready?visible.filter(x=>x[1]===id).map(x=>`<button class="parallel-item ${x[5]} ${x[5]==='period'&&(Math.min(end,x[3])-Math.max(start,x[2]))/span<.16?'short-period':''} ${pos(Math.max(start,x[2]))>75?'edge-label':''}" data-world-item="${x[0]}" title="${esc(L(...x[6]))}" aria-pressed="${x[0]===worldItemId}" aria-label="${esc(L(...x[6]))} · ${year(x[2])}${x[5]==='period'?'–'+year(x[3]):''}" style="left:${pos(Math.max(start,x[2]))}%;top:${x[5]==='period'?38+x[4]*58:310+visible.filter(v=>v[1]===id&&v[5]==='event').findIndex(v=>v[0]===x[0])*68}px;${x[5]==='period'?'width:'+((Math.min(end,x[3])-Math.max(start,x[2]))/span*100)+'%;':''}">${x[5]==='event'?`<span class="event-pin">●</span><span class="event-caption"><small>${year(x[2])}</small>${esc(L(...x[6]))}</span>`:`<span class="period-caption">${esc(L(...x[6]))}</span>`}</button>`).join(''):`<span class="parallel-empty">${L('尚未整理','Not yet curated')}</span>`}</div></section>`;}).join('')}</div></div>${item?`<section class="parallel-detail" aria-live="polite"><div class="world-kicker">${year(item[2])}${item[5]==='period'?' — '+year(item[3]):''}</div><h2>${esc(L(...item[6]))}</h2><p>${esc(L(...item[7]))}</p><button ${item[1]==='europe'?'data-world-era':'data-africa-chapter'}="${item[8]}">${L('进入历史章节与关联遗产','Explore the chapter and related heritage')} →</button></section>`:''}<p class="parallel-key">${L('当前展示精选节点，史前的更长时间尺度尚待补充。重叠只表示同时期，不自动表示相互影响。','Selected nodes are shown; the deeper prehistoric scale remains to be added. Overlap indicates shared dates, not necessarily interaction.')}</p>`;
}

// Drag starts anywhere in the chart, including labels; a short click still opens a node.
let timelineDrag=null,suppressTimelineClick=false;
document.addEventListener('pointerdown',e=>{const panel=e.target.closest('.parallel-scroll');if(!panel||e.pointerType==='touch'||e.button!==0)return;timelineDrag={panel,id:e.pointerId,x:e.clientX,left:panel.scrollLeft,moved:false};suppressTimelineClick=false;});
document.addEventListener('pointermove',e=>{const d=timelineDrag;if(!d||d.id!==e.pointerId)return;const dx=e.clientX-d.x;if(!d.moved&&Math.abs(dx)<5)return;if(!d.moved){d.moved=true;d.panel.setPointerCapture(e.pointerId);d.panel.classList.add('is-dragging');}d.panel.scrollLeft=d.left-dx;e.preventDefault();});
function stopTimelineDrag(e){const d=timelineDrag;if(!d||d.id!==e.pointerId)return;timelineDrag=null;suppressTimelineClick=d.moved;d.panel.classList.remove('is-dragging');if(d.panel.hasPointerCapture(d.id))d.panel.releasePointerCapture(d.id);}
document.addEventListener('pointerup',stopTimelineDrag);document.addEventListener('pointercancel',stopTimelineDrag);document.addEventListener('lostpointercapture',stopTimelineDrag);
document.addEventListener('click',e=>{if(suppressTimelineClick&&e.target.closest('.parallel-scroll')){e.preventDefault();e.stopImmediatePropagation();suppressTimelineClick=false;}},true);
